import itertools
def clust(cells,min_d=1):
    cells=set(cells); out=[]
    while cells:
        cur=next(iter(cells)); stack=[cur]; comp=[cur]; cells.discard(cur)
        while stack:
            r,c=stack.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    p=(r+dr,c+dc)
                    if p in cells and max(abs(p[0]-cur[0]),abs(p[1]-cur[1]))<=min_d:
                        stack.append(p); cells.discard(p); comp.append(p)
        out.append(comp)
    return out
