G=load()

def f(I):
    H=len(I); W=len(I[0])
    sepc=[r for r in range(H) if all(v==2 for v in I[r])][0]
    O=[list(row) for row in I]
    pts=[(r,c) for r in range(H) for c in range(W) if I[r][c]==4]
    for r,c in pts:
        nr,nc=r+1,c
        if 0<=nr<H and 0<=nc<W and I[nr][nc]!=4:
            O[nr][nc]=4
        # upward diagonal rays from new position, only if originally above separator and not in top row
        if r<sepc and r>0:
            for dr,dc in [(-1,-1),(-1,+1)]:
                rr,cc=nr+dr,nc+dc
                while 0<=rr<H and 0<=cc<W and I[rr][cc]!=2:
                    O[rr][cc]=4
                    rr+=dr; cc+=dc
    return O

